    let mut h2 = [0i32; 32];
    for j in 0..32 {
        let mut acc: i32 = 0;
        for i in 0..32 {
            acc = acc.saturating_add(W2[j][i].saturating_mul(h1[i]));
        }
        h2[j] = relu(acc / SCALE + B2[j]);
    }

    let mut best_idx: usize = 0;
    let mut best_val: i32 = i32::MIN;
